import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Empasy 製品ガイド","text":"Boon to business by agility.","tagline":"「変化に最適化されたソリューション」、Sync Seriesでビジネスの俊敏性(Agility)を極大化します。","actions":[{"text":"はじめる","link":"/syncverse/","type":"primary"},{"text":"すべての製品を見る","link":"#sync-series-製品群","type":"secondary"}]},"head":[["meta",{"name":"keywords","content":"テスト自動化, エンパシー, Empasy, Sync Series, SyncVerse, SyncInsight, AIオーケストレーション, マルチエージェント, AIモニタリング, SyncBoot, SyncAdmin, SyncCMS, SyncEta, マイクロサービスアーキテクチャ, MSA, ソフトウェア開発, ソリューション, デジタルトランスフォーメーション, ビジネスの俊敏性, 開発プラットフォーム, バックエンド, フロントエンド, コンテンツ管理システム, CMS, AIテスト, 自動化テスト, QA, 品質保証, CI/CD, DevOps, ウェブサイト構築, システム統合, SI, ITO, カスタムソリューション, Java, Vue.js, Vue 3, Vite, TypeScript, Freemarker, Selenium"}],["meta",{"property":"og:title","content":"Empasy Sync Series: デジタル革新のためのMSAベースソリューション | 開発, CMS, AIテスト自動化"}],["meta",{"property":"og:description","content":"EmpasyはSyncBoot, SyncAdmin, SyncCMS, SyncEtaで構成されるSync Seriesを通じて、企業のデジタル革新とビジネスの俊敏性を極大化します。MSAベースのバックエンド、フロントエンド、CMS、AIテスト自動化により開発速度を高め、品質を保証し、維持コストを削減します。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/"}]],"features":[{"title":"ビジネスの俊敏性および変化対応の最適化","details":"急激に変化するビジネス環境に合わせてソフトウェアの変更を迅速にサポートし、これにより企業の俊敏性を高め、競争力を維持できるように支援します。Sync Seriesは開発からテストまでの速度と柔軟性に焦点を当てています。"},{"title":"開発/運用効率およびユーザーフレンドリー","details":"直感的なインターフェースと組み込まれた機能により、開発者はコアビジネスロジックに集中でき、非専門家でも簡単にコンテンツを管理したりテストを自動化したりできます。"},{"title":"優れた顧客カスタマイズおよび柔軟な拡張","details":"顧客の多様なビジネス環境と要件に合わせてシステムの拡張および修正が可能であり、必要な機能だけを選択的に導入することでコスト効率を高めることができます。"},{"title":"オープンソースベースのベンダー非依存性","details":"特定のベンダーに依存しないオープンソースベースのソリューションで柔軟性を提供し、革新的な技術をいち早く導入してサービスを高度化することが容易です。"},{"title":"包括的な統合管理およびE2Eソリューション","details":"API管理、CI/CD、モニタリング、テスト自動化など、開発から運用までの全体プロセスを統合管理し、業務効率を極大化します。"},{"title":"高い安定性、品質、およびセキュリティの確保","details":"多数の構築事例を通じて検証された安定したソリューションであり、継続的なモニタリングと強力なセキュリティ機能で信頼性の高いサービスを提供します。"}],"footer":"Copyright © 2025 Empasy"},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1786514511000}`),a={name:`ja/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h2 id="empasy-ドキュメント" tabindex="-1">Empasy ドキュメント <a class="header-anchor" href="#empasy-ドキュメント" aria-label="Permalink to “Empasy ドキュメント”">​</a></h2><p>以下のドキュメントが含まれています：</p><ul><li><a href="/docs/synceta/">SyncETA</a> - コーディングなしで誰もが簡単に自動化テストを構築し、CI/CD環境に統合することで、ビジネスの変化に迅速かつ安定して対応できるよう支援する統合テスト自動化プラットフォーム。</li><li><a href="/docs/synccrawl/">SyncCrawl</a> - 自然言語コマンドでウェブデータを収集し、RAGナレッジベースを構築。ウェブ構造の変化に自動対応して運用効率を極大化し、LLMのハルシネーションのない正確で信頼性の高い回答を提供するインテリジェントな統合クローリングソリューション。</li><li><a href="/docs/synccms/">SyncCMS</a> - ビジネスの変化に合わせてウェブサイトを迅速に発展させ、非専門家でも簡単にコンテンツを管理し、柔軟に機能を拡張できる効率的なコンテンツ管理プラットフォーム。</li><li><a href="/docs/syncboot/">SyncBoot</a> - オープンソースのマイクロサービスベースの迅速な開発および効率的な運用環境を提供し、企業が急速に変化するビジネス環境に機敏に対応し、競争優位を確保できるよう支援するプラットフォーム。</li><li><a href="/docs/syncadmin/">SyncAdmin</a> - Vue 3、Vite、TypeScriptベースのオープンソース管理システムテンプレートで、再利用可能なコンポーネントと迅速な開発環境を提供し、中大型バックオフィスの開発生産性を極大化し、変化する要件に迅速に対応できるようサポートします。</li><li><a href="/docs/syncapim/">SyncApim</a> - 包括的かつ安定したAPI管理と<strong>優れたカスタマイズ性(Customization in its DNA)</strong>を通じて、企業がAPIによるデジタル革新を加速し、ビジネス競争力を強化できるよう支援する強力なプラットフォーム。</li><li><a href="/docs/syncverse/">SyncVerse</a> - 複数の特化したAIエージェントが有機的に協調し、システムインフラとビジネスロジックを自律的に管理するLLMネイティブな中央オーケストレーションプラットフォーム。</li><li><a href="/docs/syncinsight/">SyncInsight</a> - エージェントエコシステム全体の膨大なデータをリアルタイムに収集・分析し、自然言語クエリ（NLQ）を通じて直感的にビジネスインサイトを導き出すAI駆動型のインテリジェント監視センター。</li><li><a href="/docs/agile/">Agile</a> - Agileの革新のためにスクラムとカンバンを組み合わせた（スクラムバン(Scrumban)）Empasyの開発方法論。</li><li><a href="/docs/study/">Study</a> - Empasy 学習室。</li></ul><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>Empasyは、「Empathic Synergy（共感のシナジー）」というコアバリューに基づき、急速に変化するビジネス環境に機敏に対応するためのソフトウェアソリューションを開発する企業です。EmpasyはソリューションベースのSI（システム統合）およびITO（ITアウトソーシング）事業を主力としており、特に「変化に最適化されたソリューション」を最高の価値として掲げるSync Series製品群を通じて、企業のビジネス俊敏性確保を支援しています。Sync Seriesは、開発、テスト、コンテンツ管理、API管理など、ソフトウェアライフサイクル全般にわたってスピード、効率性、柔軟性を高めることを目標としています。</p><h2 id="empasyのコアバリューとビジョン" tabindex="-1">Empasyのコアバリューとビジョン <a class="header-anchor" href="#empasyのコアバリューとビジョン" aria-label="Permalink to “Empasyのコアバリューとビジョン”">​</a></h2><p>Empasyの社名である「EmpaSy」は、深い共感と協業を通じて優れた結果を生み出す「Empathic Synergy」を意味します。これは、顧客とチームメンバー間の深い理解と支持をもとに共同の目標を達成するという哲学を込めています。 Empasyは、「急速に変化するビジネス環境には迅速な対応が必要である」という認識のもと、ソフトウェアがすべての業務の中心にあり、変化するビジネス環境に迅速に対応するためには、ソフトウェアの迅速な変更が不可欠であると強調しています。これに伴い、Empasyはこのような急速な変化に効率的に対応するためのSync Seriesを開発し、「変化に最適化されたソリューション」がSync製品群の最高の価値であると明記しています。また、「Boon to business agility（ビジネスの俊敏性のための恩恵）」をスローガンに掲げ、「生きているソフトウェアを作ります」ということが会社の主要な目標の一つです。</p><h2 id="sync-series-製品群" tabindex="-1">Sync Series 製品群 <a class="header-anchor" href="#sync-series-製品群" aria-label="Permalink to “Sync Series 製品群”">​</a></h2><p>Empasyはビジネスの俊敏性を確保するためのSync Series製品群を保有しており、主要製品は以下の通りです。</p><h3 id="synccms-コンテンツ管理システム" tabindex="-1">SyncCMS: コンテンツ管理システム <a class="header-anchor" href="#synccms-コンテンツ管理システム" aria-label="Permalink to “SyncCMS: コンテンツ管理システム”">​</a></h3><ol><li>概要: ウェブサイトと管理システムを簡単に構築できるように設計されたCMSです。</li><li>主な特徴: Javaベースの安定性。高い安定性と拡張性を提供します。</li><li>モジュール化された構造: 必要に応じて選択的に機能を使用。</li><li>テンプレートサポート: ユーザー定義テンプレートによるデザインおよびレイアウト管理。</li><li>多言語サポート: グローバルなウェブサイト構築が容易。</li><li>SEO最適化: 検索エンジンの露出向上。</li><li>ユーザー権限管理: 細分化された権限設定。</li><li>RESTful APIサポート: 拡張性の向上。</li><li>Freemarkerベースのテンプレートエンジン: デザインの柔軟性を保証。</li><li>クロスプラットフォーム: 多様な環境で実行可能。</li><li>リアルタイムデータ処理: データベースの変更検知と同期。</li><li>メリット: 「開発者でなくても、マーケターや運用担当者が簡単にウェブサイトの内容を更新したり修正したりできます」、「モジュール構造のおかげで、必要な時に新しい機能を追加したり拡張したりするのもはるかに柔軟に行えます」。拡張性、ユーザーフレンドリーなインターフェース、コミュニティのサポート。ベンダーロックインやカスタマイズの限界を克服するための多様な拡張ポイントとSpringベースのウェブフレームワークを提供します。</li><li>活用事例: 企業のウェブサイト、ブログ、ニュースポータル、電子商取引プラットフォーム、政府および公共機関のポータル、迅速なプロトタイピング。</li></ol><h3 id="syncboot-java-迅速開発プラットフォーム" tabindex="-1">SyncBoot: Java 迅速開発プラットフォーム <a class="header-anchor" href="#syncboot-java-迅速開発プラットフォーム" aria-label="Permalink to “SyncBoot: Java 迅速開発プラットフォーム”">​</a></h3><ol><li>概要: Javaベースのオープンソース迅速開発プラットフォームであり、企業向けアプリケーションの開発効率化を目的としています。</li><li>技術スタック: バックエンド (Spring Boot, Spring Cloud, MyBatis-Plus, JWT)、フロントエンド (Vue.js, Ant Design Vue, React)、データベース (MySQL, Oracleなど)、モジュール化 (権限管理, ワークフロー, レポート, ダッシュボード)、クラウドサポート (マイクロサービスアーキテクチャ)。</li><li>主な機能: システム管理 (ユーザー, ロール, メニュー, データ権限)、データ視覚化 (ドラッグ＆ドロップダッシュボード, チャートレポート)、モバイル対応、APIドキュメント (Swagger統合)。</li><li>メリット: 「安定したJavaとSpring Boot Frameworkをベースにしています。企業環境でよく使われる機能、例えば権限管理やセキュリティのような複雑なモジュールをあらかじめ作って提供します」、「開発者はこのような基本的な機能を作る時間を減らし、実際のビジネスロジックの開発にもっと集中できるようになります」、「標準技術ベースなので、開発者が容易に適応し、迅速に企業向けアプリケーションを作れるよう支援します」。低い学習曲線、活発なコミュニティ、拡張性。</li><li>活用事例: ERP/CRMシステム、内部管理プラットフォーム、データ分析ダッシュボードなどの中小規模企業向けアプリケーション。MSA運用環境の確保、サービスの安定化、オープンソースベース、DevOps開発/運用環境の定着、障害対応力の向上、高度化ロードマップの確保などの期待効果を提供します。</li></ol><h3 id="syncadmin-vue-3-管理システムテンプレート" tabindex="-1">SyncAdmin: Vue 3 管理システムテンプレート <a class="header-anchor" href="#syncadmin-vue-3-管理システムテンプレート" aria-label="Permalink to “SyncAdmin: Vue 3 管理システムテンプレート”">​</a></h3><ol><li>概要: Vue 3, Vite, TypeScriptベースのオープンソース管理システムテンプレートで、中大型バックオフィスおよび管理者ダッシュボードの開発に最適化されています。</li><li>主な特徴: 最新の技術スタック (Vue 3, Vite, TypeScript, Pinia, Vue Routerなど) を活用。</li><li>多言語サポート: 内蔵の国際化 (i18n) 機能。</li><li>権限管理: 動的ルーティング、ボタン単位の制御を含む細分化されたアクセス制御。</li><li>テーマカスタマイズ: 多様なテーマおよびダークモードのサポート。</li><li>Mockサーバー内蔵: Nitroベースの高性能Mockサーバーを提供。</li><li>多様なUIフレームワークサポート: Ant Design Vue, Naive UI, Element Plusなどと互換性あり。</li><li>モノレポ構造: Pnpm, TurboRepoを活用。</li><li>豊富なコンポーネント: 再利用可能なコンポーネント、ユーティリティ、フックを提供。</li><li>メリット: 「再利用可能なコンポーネントとViteというビルドツール」により、「複雑な管理画面もレゴを組み立てるように迅速に作ることができ」、「開発中に何かを変更するとほぼリアルタイムで画面に反映されます。そのため、開発スピード自体が目に見えて速くなります」。</li><li>活用事例: 企業内システム (ERP, CRMなど)、管理者ダッシュボード、学習および教育用。</li></ol><h3 id="sync-apim-api-管理プラットフォーム" tabindex="-1">Sync APIM: API 管理プラットフォーム <a class="header-anchor" href="#sync-apim-api-管理プラットフォーム" aria-label="Permalink to “Sync APIM: API 管理プラットフォーム”">​</a></h3><ol><li>概要: APIによる価値創出とデジタル革新をリードするAPI管理プラットフォームです。「Customization in its DNA」を強調し、顧客に合わせたソリューションを提供します。</li><li>主な特徴: 安定性（高可用性と安定した運用環境を保証）。</li><li>セキュリティ: OAuth 2.0、JWT、APIキーによる多層セキュリティ。</li><li>統合管理: APIの作成、デプロイ、セキュリティ、モニタリング、分析を1か所で処理。</li><li>開発者フレンドリー: 直感的な開発者ポータルと豊富なドキュメント。</li><li>拡張性: 大規模なトラフィック処理と多様な環境に柔軟に対応できるクラウドネイティブアーキテクチャ。</li><li>ポリシー管理: 呼び出し制限、アラート、統計などの多様なポリシーを提供し、顧客特化のポリシー開発が可能。</li><li>API管理: 集中型API登録およびグループ分類。</li><li>APIテスト: エンドポイントの呼び出しと応答の検証。</li><li>モニタリング: APIのパフォーマンスと状態の準リアルタイム追跡と分析。</li><li>システムアラート: 重要なイベント発生時の管理者アラート提供。</li><li>メリット: ビジネスの拡張（パートナーシップおよび開発者エコシステムの構築）、セキュリティ強化（データ暗号化、無断アクセス防止）、APIパフォーマンス最適化（応答速度向上）、コスト削減（APIライフサイクルの自動化、開発時間の短縮）、運用効率の向上、API中心のエコシステム構築、ビジネスモデルの拡張、企業競争力の強化。カスタマイズ可能なシステムを通じて、柔軟なカスタマイズ、コスト効率、迅速なデプロイ、高い満足度を提供します。</li><li>期待効果: API管理プロセスの自動化、社内外の開発者間の協業強化、新しいAPIサービスの開発と収益創出、APIベースの革新的なサービス提供と市場のリード。</li></ol><h3 id="synceta-ウェブ自動化テストプラットフォーム" tabindex="-1">SyncETA: ウェブ自動化テストプラットフォーム <a class="header-anchor" href="#synceta-ウェブ自動化テストプラットフォーム" aria-label="Permalink to “SyncETA: ウェブ自動化テストプラットフォーム”">​</a></h3><ol><li>概要: Seleniumベースのエンジン上に構築された、ウェブ自動化テストをサポートする統合テスト自動化プラットフォームです。</li><li>主な特徴: ウェブ、モバイル、APIテストなど多様なテストをサポート。</li><li>デュアルインターフェース: スクリプトベース（Groovy/Java）およびキーワード/GUIベースのコードレスモードを提供。</li><li>自動化ツール: テストレコーディング (Record)、オブジェクトスパイ (Object Spy)、デバッグ、データ駆動型テスト。</li><li>統合管理: テストケース、スイート、実行結果の管理。</li><li>CI/CD統合: Jenkins, Azure DevOps, Git, Slackなどと連携。</li><li>ストーリーベーステスト: シナリオをフローチャートで繋いで動的に実行。</li><li>リアルタイム通信とAI画面検証: ソケット通信およびAIを活用したデータ検証。</li><li>AIテストデータの自動生成と管理: モックアップデータの自動生成。</li><li>動的テストCHAINING: 条件に応じた連鎖的なシナリオ実行。</li><li>メリット: 「素早く変更するとどうしてもエラーの可能性が高まります。SyncEtaはまさにその部分を解決してくれます」、「簡単に言えば、ユーザーがウェブサイトを使用する行動を自動的にスクリプトにして、自動でテストを実行するものです」、「ユーザーフレンドリーな開発環境、IDEを提供し、テストの作成から実行、結果の報告までを非常に効率的に管理できるようにします」、「特に重要なのはCI/CD、つまり継続的統合・継続的デプロイツールと連携できる点です。開発者がコードを変更すると、自動的にテストしてデプロイまで繋げてくれるので、ソフトウェアの変更事項を本当に素早く安定して反映できるようになります」。ユーザーフレンドリー（コーディング経験の少ないユーザーでも容易）、多様なテストタイプのサポート、初期コストの削減と維持コストの最小化、効率的なリソース管理、コラボレーションの強化、スピードの向上とテスト拡張性の確保、持続可能な品質管理、顧客満足度の向上。コードなしで簡単かつ迅速なウェブテスト自動化環境を提供します。</li><li>活用事例: 自動化テストによる市場投入期間の短縮、CI/CDおよび外部システム統合、テストの品質および信頼性強化、テストの管理および実行効率の向上。</li></ol><h3 id="syncverse-インテリジェント・マルチエージェント・オーケストレーション" tabindex="-1">SyncVerse: インテリジェント・マルチエージェント・オーケストレーション <a class="header-anchor" href="#syncverse-インテリジェント・マルチエージェント・オーケストレーション" aria-label="Permalink to “SyncVerse: インテリジェント・マルチエージェント・オーケストレーション”">​</a></h3><ol><li>概要: 個別に動作するソフトウェアモジュールを一つの有機的なAIエコシステムに接続する中央制御プラットフォームです。</li><li>主な特徴: LLM中心のシステム運用、Agent-to-Agent（A2A）通信網の構築、自然言語ベースの対話型運用統制のサポート。</li><li>メリット: 開発者がインフラ拡張から解放され、意思決定に集中できるようにエージェントが主体的にシステム変更事項を提案・実行し、プライベートAI環境で企業のセキュリティを完全に維持します。</li></ol><h3 id="syncinsight-ai駆動型インテリジェントデータ監視センター" tabindex="-1">SyncInsight: AI駆動型インテリジェントデータ監視センター <a class="header-anchor" href="#syncinsight-ai駆動型インテリジェントデータ監視センター" aria-label="Permalink to “SyncInsight: AI駆動型インテリジェントデータ監視センター”">​</a></h3><ol><li>概要: システム内外に散在するデータを統合収集し、AIがリアルタイムで分析してビジネスの意思決定を支援する監視プラットフォームです。</li><li>主な特徴: リアルタイムデータストリーミング分析、異常検知（Anomaly Detection）、自然言語クエリ（NLQ）に基づくカスタムチャート作成。</li><li>メリット: 複雑なクエリやダッシュボード設計の知識がなくても日常的な質問だけでインサイトを得ることができ、AIが問題状況に対する最適な解決アクションを先制的に提案します。</li></ol><h2 id="empasyの事業分野と競争力" tabindex="-1">Empasyの事業分野と競争力 <a class="header-anchor" href="#empasyの事業分野と競争力" aria-label="Permalink to “Empasyの事業分野と競争力”">​</a></h2><p>Empasyはシステム統合（SI）、IT維持管理（ITO）、ソリューション事業、モバイル事業を主力としています。特に独自開発したSyncCMSとSyncBootソリューションを通じて、顧客に最適なサービスを提供しています。 競争力のコアポイント: 先進技術に基づく効率的な協業能力、多様な産業分野の業務環境要件に合った最適なITシステム構築の経験、大企業および中堅企業の戦略的ビジネスパートナーとしてのITO事業遂行、マイクロサービスベースの柔軟なシステム構築プラットフォーム (SyncBoot)、体系的なコンテンツ管理および拡張可能なウェブサービス開発プラットフォーム (SyncCMS)、モバイルアプリ開発からシステム連携および運用環境の提供能力。</p><h2 id="構築事例" tabindex="-1">構築事例 <a class="header-anchor" href="#構築事例" aria-label="Permalink to “構築事例”">​</a></h2><p>Empasyは多様な顧客を対象に、Sync Series製品を活用した成功的な構築事例を保有しています。主な事例は以下の通りです。</p><ol><li>ホームプラス MISシステムの再構築 (SyncBoot)</li><li>SKマジック MagicPlus BO改編プロジェクト (SyncBoot)</li><li>サムスンDS ブランドデスクサイト構築 (SyncCMS)</li><li>KT ESGポータルサイト構築 (SyncCMS)</li><li>LXハウシス 海外グローバルウェブサイト構築および保守 (SyncCMS)</li><li>SKマジック e-カタログシステム構築 (SyncCMS)</li><li>天才教育 Tセルパ リニューアル構築 (SyncCMS)</li><li>飛上教育 AIDT (SyncEta)</li><li>現代自動車 ログ収集 (SyncEta)</li><li>ペンタセキュリティ (SyncApim)</li></ol><h2 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h2><p>EmpasyのSync Series製品群は、急速に変化するビジネス環境において企業が機敏に対応し、競争力を確保できるよう支援することに焦点を当てています。各製品は、フロントエンド開発、バックエンド開発、コンテンツ管理、テスト自動化、API管理など、ソフトウェアライフサイクルのコア領域においてスピード、効率性、柔軟性を提供する技術的な特徴とメリットを持っています。「変化に最適化されたソリューション」というEmpasyの哲学は、Sync Series製品群全般にわたって具現化されており、検証された技術力と豊富な構築経験をもとに、顧客のビジネスの成功に貢献しています。Sync Seriesは単なる機能リストの羅列を超え、企業の変革管理という難しい課題を解決するためのEmpasyの悩みとその答えが込められたソリューションです。</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};